import{_ as o,o as r,c as a,a4 as d}from"./chunks/framework.BBs01uty.js";const q=JSON.parse('{"title":"RAG vs 微调（Fine-tuning）","description":"","frontmatter":{},"headers":[],"relativePath":"ai-agent/rag/rag-vs-finetuning.md","filePath":"ai-agent/rag/rag-vs-finetuning.md"}'),n={name:"ai-agent/rag/rag-vs-finetuning.md"};function e(i,t,l,s,u,g){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="rag-vs-微调-fine-tuning" tabindex="-1">RAG vs 微调（Fine-tuning） <a class="header-anchor" href="#rag-vs-微调-fine-tuning" aria-label="Permalink to &quot;RAG vs 微调（Fine-tuning）&quot;">​</a></h1><blockquote><p>面试高频题：&quot;你的知识库为什么用 RAG 不用微调？&quot; 本文先把<strong>微调</strong>讲透，再回答这个问题。RAG 本身见 <a href="./introduction.html">RAG 入门</a>。</p></blockquote><h2 id="一、微调-fine-tuning-是什么" tabindex="-1">一、微调（Fine-tuning）是什么 <a class="header-anchor" href="#一、微调-fine-tuning-是什么" aria-label="Permalink to &quot;一、微调（Fine-tuning）是什么&quot;">​</a></h2><p><strong>一句话</strong>：拿一个已经预训练好的大模型，用你自己的数据<strong>继续训练</strong>，去改动它的参数（权重），让它更贴合你的任务或领域。</p><p>关键在&quot;改动参数&quot;——微调之后，<strong>模型本身变了</strong>。你喂给它的知识或风格，被&quot;烧&quot;进了那几十亿个参数里。</p><h3 id="一个类比-闭卷考试-vs-开卷考试" tabindex="-1">一个类比：闭卷考试 vs 开卷考试 <a class="header-anchor" href="#一个类比-闭卷考试-vs-开卷考试" aria-label="Permalink to &quot;一个类比：闭卷考试 vs 开卷考试&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>微调（Fine-tuning）</th><th>RAG（检索增强）</th></tr></thead><tbody><tr><td>类比</td><td><strong>闭卷考试</strong></td><td><strong>开卷考试</strong></td></tr><tr><td>知识在哪</td><td>模型&quot;脑子&quot;里（参数）</td><td>外部资料库（向量库）</td></tr><tr><td>模型变不变</td><td><strong>变</strong>（权重被改写）</td><td><strong>不变</strong>（模型原封不动）</td></tr><tr><td>加/换知识</td><td>重新训练</td><td>重建索引</td></tr><tr><td>能否说出出处</td><td>不能</td><td>能（引用来源）</td></tr></tbody></table><p><code>qwen3:8b</code> 微调，就是拿你的数据再喂给它、跑一轮训练，把&quot;你的东西&quot;刻进那 80 亿个参数里。</p><h3 id="微调的主要类型" tabindex="-1">微调的主要类型 <a class="header-anchor" href="#微调的主要类型" aria-label="Permalink to &quot;微调的主要类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>成本</th></tr></thead><tbody><tr><td><strong>全量微调（Full FT）</strong></td><td>更新模型所有参数</td><td>最高，通常要多卡 GPU</td></tr><tr><td><strong>LoRA / QLoRA（PEFT）</strong></td><td>冻结原模型，只训练一小撮附加参数</td><td>低，个人显卡可玩</td></tr><tr><td><strong>SFT（指令微调）</strong></td><td>用&quot;指令 → 回答&quot;成对数据，教模型怎么答</td><td>中</td></tr><tr><td><strong>RLHF / DPO</strong></td><td>用人类偏好数据对齐模型的&quot;口味&quot;</td><td>高</td></tr></tbody></table><blockquote><p>记忆点：<strong>微调擅长教&quot;怎么答&quot;（风格、格式、领域黑话、指令遵循），不擅长注入&quot;答什么&quot;（频繁变动的事实知识）。</strong></p></blockquote><h2 id="二、rag-和微调解决的不是同一个问题" tabindex="-1">二、RAG 和微调解决的不是同一个问题 <a class="header-anchor" href="#二、rag-和微调解决的不是同一个问题" aria-label="Permalink to &quot;二、RAG 和微调解决的不是同一个问题&quot;">​</a></h2><ul><li><strong>RAG 管&quot;答什么&quot;</strong>：知识放在外部，回答时现查现用（检索 → 增强 → 生成）。</li><li><strong>微调管&quot;怎么答&quot;</strong>：把风格、格式、领域表达习惯训练进模型。</li></ul><p>所以两者不是替代关系。先想清楚你的目标是&quot;让模型记住具体知识&quot;还是&quot;改变模型的表达方式&quot;。</p><h2 id="三、rag-vs-微调-对比" tabindex="-1">三、RAG vs 微调 对比 <a class="header-anchor" href="#三、rag-vs-微调-对比" aria-label="Permalink to &quot;三、RAG vs 微调 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>RAG</th><th>微调（Fine-tuning）</th></tr></thead><tbody><tr><td>知识更新</td><td>实时（重建索引即可）</td><td>需重新训练，慢且贵</td></tr><tr><td>成本</td><td>低（只做 embedding + 检索）</td><td>高（训练需 GPU、数据标注）</td></tr><tr><td>数据量要求</td><td>低（几篇文档就能用）</td><td>高（需大量高质量样本）</td></tr><tr><td>可解释性</td><td>可追溯来源</td><td>黑盒，说不出出处</td></tr><tr><td>幻觉控制</td><td>较好（原文强约束）</td><td>仍有幻觉，甚至更&quot;自信&quot;</td></tr><tr><td>灾难性遗忘</td><td>无（模型不变）</td><td>有风险（覆盖原有能力）</td></tr><tr><td>隐私/可控</td><td>数据在向量库，可精确增删</td><td>知识融进参数，难以&quot;删干净&quot;</td></tr><tr><td>擅长</td><td>动态知识、问答、检索</td><td>风格迁移、格式固定、领域术语</td></tr></tbody></table><h2 id="四、为什么-知识库问答-用-rag-不用微调" tabindex="-1">四、为什么&quot;知识库问答&quot;用 RAG 不用微调 <a class="header-anchor" href="#四、为什么-知识库问答-用-rag-不用微调" aria-label="Permalink to &quot;四、为什么&quot;知识库问答&quot;用 RAG 不用微调&quot;">​</a></h2><p>结合本项目（Koa + TS，Chroma 向量库，本地 Ollama 部署 <code>qwen3:8b</code> + <code>bge-m3</code>）：</p><ol><li><strong>知识持续更新</strong>：知识库还在不断加文章。RAG 只需重跑一次 <code>pnpm kb index</code> 重建索引，分钟级；微调要重新准备数据 + 重新训练，慢且贵。</li><li><strong>成本与资源</strong>：微调 <code>qwen3:8b</code> 需要 GPU 显存和大量数据；本项目用本地 Ollama + Chroma，消费级机器即可跑。</li><li><strong>数据量不够</strong>：微调需要大量高质量&quot;问题-答案&quot;样本，个人知识库这点量很容易过拟合；RAG 对样本量要求低。</li><li><strong>可溯源（面试最爱追问）</strong>：RAG 能给出&quot;这段来自哪篇文档&quot;，用户可点开源文验证；微调把知识混进参数，答出来也说不出出处。</li><li><strong>抗幻觉</strong>：RAG 用检索到的原文做强约束（&quot;只根据以下资料回答&quot;）；微调模型容易&quot;自信地胡说&quot;。</li><li><strong>灾难性遗忘</strong>：微调会覆盖模型原有的通用能力，&quot;学新的忘旧的&quot;；RAG 完全不动模型，通用能力原样保留。</li><li><strong>可控可删除</strong>：RAG 里删掉某篇文档，检索立刻搜不到；微调进参数的知识，几乎无法&quot;删干净&quot;。</li></ol><h2 id="五、进阶-什么时候才需要微调" tabindex="-1">五、进阶：什么时候才需要微调 <a class="header-anchor" href="#五、进阶-什么时候才需要微调" aria-label="Permalink to &quot;五、进阶：什么时候才需要微调&quot;">​</a></h2><p>不是说微调没用，而是它解决的是另一类问题：</p><ul><li><strong>固定输出风格/格式</strong>：要求模型始终按某模板、始终带引用格式输出。</li><li><strong>领域黑话理解</strong>：让模型更懂某行业/公司内部的术语与表达。</li><li><strong>提升检索质量</strong>：微调 embedding 模型或 reranker，让&quot;检索得更准&quot;。</li><li><strong>组合打法</strong>：<strong>RAG 供给知识 + 微调约束风格</strong>——这是很多生产系统的实际做法。</li></ul><h2 id="六、面试速答版-30-秒" tabindex="-1">六、面试速答版（30 秒） <a class="header-anchor" href="#六、面试速答版-30-秒" aria-label="Permalink to &quot;六、面试速答版（30 秒）&quot;">​</a></h2><blockquote><p>&quot;RAG 和微调解决的不是同一个问题——RAG 管&#39;答什么&#39;（知识），微调管&#39;怎么答&#39;（风格、格式、领域术语）。我的知识库持续更新、数据量不大、又要求回答能给出处，这几个点正好都是 RAG 的强项、微调的短板（更新要重训、成本高、易灾难性遗忘、不可溯源），所以我选 RAG。真要提升，我会用微调 LoRA 去优化输出格式或微调 reranker 提升检索，而不是拿它来存知识。&quot;</p></blockquote><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./introduction.html">RAG 入门</a> —— RAG 原理与工程实践</li><li><a href="./knowledge-base.html">AI 知识库实战</a> —— 本知识库的 RAG 实现</li><li><a href="./../llm-landscape.html">大模型全景介绍</a> —— 模型与部署选型</li></ul>',26)])])}const c=o(n,[["render",e]]);export{q as __pageData,c as default};
